import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as i,c as d,o as n,ag as s,G as r}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Cindy 源码解读：三个 harness 是怎么被接进同一个工作区的","description":"读 makecindy/cindy 的源码，讲清四件事：Codex 直接实现在 maker-core 里而不是一个独立的包；手机控制电脑靠一张默认拒绝的白名单；Orca 用 MCP 让一个 Lead 指挥多个 Worker；各种模型协议靠本地回环代理互译。附仓库地图、从源码跑起来的步骤，以及已验证、推断、未知三张清单。","frontmatter":{"title":"Cindy 源码解读：三个 harness 是怎么被接进同一个工作区的","description":"读 makecindy/cindy 的源码，讲清四件事：Codex 直接实现在 maker-core 里而不是一个独立的包；手机控制电脑靠一张默认拒绝的白名单；Orca 用 MCP 让一个 Lead 指挥多个 Worker；各种模型协议靠本地回环代理互译。附仓库地图、从源码跑起来的步骤，以及已验证、推断、未知三张清单。","domain":"product","tags":["source-code","electron","harness","device-link"],"role":"deep-dive","pageClass":"wide-figures","source_revision":"6fdec7fb89b955be548c3f5cc9a42d83bf174aa3"},"headers":[],"relativePath":"zh/products/cindy/source.md","filePath":"zh/products/cindy/source.md","lastUpdated":1795764761000}'),o={name:"zh/products/cindy/source.md"};function c(h,e,l,p,k,g){const a=i("DocDiagram");return n(),d("div",null,[e[0]||(e[0]=s("",29)),r(a,{src:"/diagrams/cindy-session-flow.svg",alt:"这张时序图按编号回答一个问题：你在界面里发出一句话，中间经过哪些对象、按什么顺序到达 harness，结果又怎样回到界面。图里有六条竖向泳道，从左到右是：界面，也就是 Renderer；预加载桥，也就是 preload；主进程，泳道里写着 IPC 处理器和输入协调器两个名字；Maker 与 Session，同属 maker-core；harness 适配器；harness 子进程。本地 SQLite 数据库是第九个对象，画成主进程泳道里的一个标注框。圆标里的数字就是顺序；同一个编号下有几条箭头时，表示这一步经几个对象接力传过去。实线是命令或调用，虚线是事件、广播与返回。第一步，界面经预加载桥调用 maker:send，带着 sessionId 与消息，进入主进程里由 ipcMain.handle 注册的处理器。第二步，主进程把输入交给输入协调器：排队、落库，并检查这个任务有没有正在跑的一轮。第三步，协调器经 Maker 取到或恢复对应的 Session。第四步，Session.send 进入 dispatchSend：确认没有在跑的一轮，为本轮预留一个代号。第五步，Session 调用 handle.send，进入 harness 适配器。第六步，适配器把消息翻译成该 harness 自己的协议，发给子进程：Codex 是 turn/start，Claude Code 是 SDK query，Pi 是 RPC。第七步，子进程执行：调用模型、读写文件、跑命令。第八步，harness 的原始输出送到适配器，适配器把它翻译成统一事件，例如 text、tool_use、tool_result、turn_diff，再送给 Session。第九步，Session 把事件分发给监听者；主进程把消息写入本地 SQLite，并把事件广播回界面。第十步，需要确认的操作以 interaction_request 经 Session 和主进程回到界面，停在界面等用户决定；用户的决定再经主进程和 Session 交到适配器，由适配器回传给子进程；找不到对应订阅者时按拒绝处理。第十一步，子进程报告本轮结束，Session 收到 done，界面恢复可输入。本图省略了：服务端或云端，因为本机任务的一轮不经过 Cindy 服务；手机与 Device Link，那是另一条链路；任何耗时数字；写数据库的具体函数与表结构。",width:1020}),e[1]||(e[1]=s("",69))])}const F=t(o,[["render",c]]);export{f as __pageData,F as default};
